def minPath(grid, k):
    from collections import deque
    import heapq

    n = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Priority queue: (lexicographical order, current position, path, current value)
    heap = []
    # Initialize the heap with all starting positions
    for i in range(n):
        for j in range(n):
            val = grid[i][j]
            heapq.heappush(heap, (val, i, j, [val]))

    # Visited set to avoid revisiting the same state (position, path)
    visited = set()

    while heap:
        val, x, y, path = heapq.heappop(heap)
        state = (x, y, tuple(path))
        if state in visited:
            continue
        visited.add(state)

        if len(path) == k:
            return path

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n:
                new_val = grid[nx][ny]
                new_path = path + [new_val]
                new_state = (nx, ny, tuple(new_path))
                if new_state not in visited:
                    heapq.heappush(heap, (new_val, nx, ny, new_path))

