        elif char == ']':
            balance -= 1
            if balance < 0:
                return False
    return has_nested

def check_if_last_char_is_a_letter(txt):
    if not txt:
        return False
    words = txt.split()
    if not words:
        return False
    last_word = words[-1]
    if not last_word:
        return False
    return last_word[-1].isalpha()

def can_arrange(arr):
    for i in range(1, len(arr)):
        if arr[i] < arr[i-1]:
            return i
    return -1

def largest_smallest_integers(lst):
    negatives = [x for x in lst if x < 0]
    positives = [x for x in lst if x > 0]

    a = max(negatives) if negatives else None
    b = min(positives) if positives else None

    return (a, b)

def compare_one(a, b):
    def to_float(value):
        if isinstance(value, (int, float)):
            return value
        elif isinstance(value, str):
            # Replace commas and dots with dots for consistent parsing
            value = value.replace(',', '.')
            return float(value)
        else:
            return None

    a_val = to_float(a)
    b_val = to_float(b)

    if a_val is None or b_val is None:
        return None

    if a_val > b_val:
        return a
    elif a_val < b_val:
        return b
    else:
        return None

def special_factorial(n):
    result = 1
    for i in range(1, n+1):
        result *= i
    return result

def fix_spaces(text):
    result = []
    spaces = 0
    for char in text:
        if char == ' ':
            spaces += 1
        else:
            if spaces > 0:
                if spaces > 2:
                    result.append('-')
                else:
                    result.append('_' * spaces)
                spaces = 0
            result.append(char)
    if spaces > 0:
        if spaces > 2:
            result.append('-')
        else:
            result.append('_' * spaces)
    return ''.join(result)

def file_name_check(file_name):
    import re
    if '.' not in file_name:
        return 'No'
    name_part, ext_part = file_name.split('.', 1)
    if len(name_part) == 0 or not re.match(r'^[a-zA-Z]', name_part):
        return 'No'
    if ext_part not in ['txt', 'exe', 'dll']:
        return 'No'
    if sum(1 for c in file_name if c.isdigit()) > 3:
        return 'No'
    return 'Yes'

def sum_squares(lst):
    total = 0
    for i in range(len(lst)):
        if i % 3 == 0:
            total += lst[i] ** 2
        elif i % 4 == 0:
            total += lst[i] ** 3
    return total

def words_in_sentence(sentence):
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    result = [word for word in words if is_prime(len(word))]
    return ' '.join(result)

def simplify(x, n):
    from fractions import Fraction
    return Fraction(x) * Fraction(n) == Fraction(x) * Fraction(n)

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))

    return sorted(nums, key=lambda x: (digit_sum(x), nums.index(x)))

def specialFilter(nums):
    count = 0
    for num in nums:
        if num > 10:
            s = str(num)
            first = int(s[0])
            last = int(s[-1])
            if first % 2 == 1 and last % 2 == 1:
                count += 1
    return count

def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]
    if planet1 not in planets or planet2 not in planets:
        return ()
    idx1 = planets.index(planet1)
    idx2 = planets.index(planet2)
    if idx1 > idx2:
        idx1, idx2 = idx2, idx1
    return tuple(planets[idx1+1:idx2])

def x_or_y(n, x, y):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    return x if is_prime(n) else y

def cycpattern_check(a, b):
    rotations = [b[i:] + b[:i] for i in range(len(b))]
    return any(rot in a for rot in rotations)

def even_odd_count(num):
    even = 0
    odd = 0
    for digit in str(abs(num)):
        if int(digit) % 2 == 0:
            even += 1
        else:
            odd += 1
    return (even, odd)

def int_to_mini_roman(number):
    val = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
    syms = ["m", "cm", "d", "cd", "c", "xc", "l", "xl", "x", "ix", "v", "iv", "i"]
    res = ""
    for i in range(len(val)):
        while number >= val[i]:
            res += syms[i]
            number -= val[i]
    return res

def right_angle_triangle(a, b, c):
    sides = sorted([a, b, c])
    return sides[0]**2 + sides[1]**2 == sides[2]**2

def find_max(words):
    max_unique = -1
    result = ""
    for word in words:
        unique = len(set(word))
        if unique > max_unique:
            max_unique = unique
            result = word
        elif unique == max_unique:
            if word < result:
                result = word
    return result

def eat(number, need, remaining):
    total_eaten = number + need
    if remaining >= need:
        return [total_eaten, remaining - need]
    else:
        return [number + remaining, 0]

def do_algebra(operator, operand):
    expression = str(operand[0])
    for i in range(len(operator)):
        expression += operator[i] + str(operand[i+1])
    return eval(expression)

def solve(s):
    result = []
    has_letter = False
    for char in s:
        if char.isalpha():
            has_letter = True
            if char.islower():
                result.append(char.upper())
            else:
                result.append(char.lower())
        else:
            result.append(char)
    if not has_letter:
        return s[::-1]
    return ''.join(result)

import hashlib

def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.
    """
    if not text:
        return None
    return hashlib.md5(text.encode()).hexdigest()

def generate_integers(a, b):
    """
    Given two positive integers a and b, return the even digits between a
    and b, in ascending order.
    """
    result = []
    start = min(a, b)
    end = max(a, b)
    for num in range(start, end + 1):
        for digit in str(num):
            if int(digit) % 2 == 0:
                result.append(int(digit))
    return result
